export const REGION_IDS=Object.keys(REGIONS);
export function regionId(id){return id==='dungeon'?'garden':Object.hasOwn(REGIONS,id)?id:'town';}
export function regionHeight(id,x,z){switch(regionId(id)){case'base':case'town':return .5;case'garden':return .5+Math.max(0,Math.min(1,(x-1120)/320))*2.4;case'aqueduct':return .5+Math.max(0,Math.min(1,(z-736)/416))*2.4;case'archive':return .5+Math.max(0,Math.min(1,(x-1504)/480))*4.8;}}
export function regionContains(id,x,z){return REGIONS[regionId(id)].platforms.some(p=>x>=p.x&&z>=p.z&&x<p.x+p.w&&z<p.z+p.h);}
export function facing8(dx,dy,yaw=0){const x=dx*Math.cos(yaw)-dy*Math.sin(yaw),y=dx*Math.sin(yaw)+dy*Math.cos(yaw);if(Math.hypot(x,y)<1e-6)return null;return ['east','southeast','south','southwest','west','northwest','north','northeast'][(Math.round(Math.atan2(y,x)/(Math.PI/4))+8)%8];}
